// Validate and normalize the ingest webhook payload.
// Required: source_type, notebook, title
// Optional: content (required for markdown), url/source_url (for url/gdrive), doc_id
const body = $input.first().json.body || $input.first().json;

const required = ['source_type', 'notebook', 'title'];
for (const field of required) {
  if (!body[field]) throw new Error(`Missing required field: ${field}`);
}

const validNotebooks = ['kong', 'personal', 'music'];
if (!validNotebooks.includes(body.notebook)) {
  throw new Error(`Invalid notebook '${body.notebook}'. Must be one of: ${validNotebooks.join(', ')}`);
}

const validSourceTypes = ['pdf', 'url', 'markdown', 'gdrive'];
if (!validSourceTypes.includes(body.source_type)) {
  throw new Error(`Invalid source_type '${body.source_type}'. Must be one of: ${validSourceTypes.join(', ')}`);
}

if (body.source_type === 'markdown' && !body.content) {
  throw new Error('content is required for source_type=markdown');
}

const docId = body.doc_id || crypto.randomUUID();

return [{
  json: {
    doc_id: docId,
    source_type: body.source_type,
    notebook: body.notebook,
    title: body.title,
    content: body.content || '',
    source_url: body.url || body.source_url || '',
    ingested_at: new Date().toISOString(),
  }
}];

// Split document content into 500-word chunks with 50-word overlap.
// Each chunk gets a crypto.randomUUID() that becomes:
//   - The Neo4j Chunk.id
//   - The Qdrant point ID
// This fixes the composite-ID bug (Spec #2) and enables neo4j_chunk_id linkage.
const item = $input.first().json;
const words = (item.content || '').trim().split(/\s+/).filter(Boolean);

if (words.length === 0) {
  throw new Error(`Document '${item.title}' has empty content — nothing to ingest`);
}

const CHUNK_SIZE = 500;
const OVERLAP = 50;

const chunks = [];
let start = 0;

while (start < words.length) {
  const end = Math.min(start + CHUNK_SIZE, words.length);
  chunks.push(words.slice(start, end).join(' '));
  if (end === words.length) break;
  start += CHUNK_SIZE - OVERLAP;
}

const total = chunks.length;
return chunks.map((text, idx) => ({
  json: {
    doc_id: item.doc_id,
    source_type: item.source_type,
    notebook: item.notebook,
    title: item.title,
    source_url: item.source_url,
    ingested_at: item.ingested_at,
    chunk_id: crypto.randomUUID(),
    chunk_text: text,
    chunk_index: idx,
    total_chunks: total,
  }
}));

// Call Kong /notebooklm/chat (llama3.2) to summarize the chunk and extract tags.
// Falls back to empty summary/tags on error so a slow/unavailable LLM
// does not block the full ingest.
const item = $input.item.json;

const kongUrl = process.env.KONG_PROXY_URL;
if (!kongUrl) throw new Error('KONG_PROXY_URL env var not set in n8n container');

const prompt =
  'Summarize the following text in 2-3 sentences, then list 3-7 keyword tags.\n' +
  'Return ONLY valid JSON with no explanation or markdown fences:\n' +
  '{"summary": "...", "tags": ["tag1", "tag2"]}\n\n' +
  'Text:\n' + item.chunk_text;

let summary = '';
let tags = [];

try {
  const res = await $helpers.httpRequest({
    method: 'POST',
    url: `${kongUrl}/notebooklm/chat`,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model: 'llama3.2',
      messages: [{ role: 'user', content: prompt }],
      stream: false,
    }),
  });

  const parsed = typeof res === 'string' ? JSON.parse(res) : res;
  const content =
    parsed?.message?.content ||
    parsed?.choices?.[0]?.message?.content ||
    '';

  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const data = JSON.parse(jsonMatch[0]);
    summary = typeof data.summary === 'string' ? data.summary : '';
    tags = Array.isArray(data.tags) ? data.tags.map(String) : [];
  }
} catch (err) {
  console.warn(`[Summarize] chunk ${item.chunk_index} of '${item.title}': ${err.message}`);
}

return [{ json: { ...item, summary, tags } }];

// Call Kong /notebooklm/chat (llama3.2) to extract graph entities.
// Retries once on malformed JSON. Falls back to empty arrays.
// Spec #2 AC: concepts[], relationships[], events[] written to Neo4j.
const item = $input.item.json;

const kongUrl = process.env.KONG_PROXY_URL;
if (!kongUrl) throw new Error('KONG_PROXY_URL env var not set in n8n container');

const prompt =
  'Extract knowledge graph entities from the text below.\n' +
  'Return ONLY valid JSON with no explanation or markdown fences:\n' +
  '{\n' +
  '  "concepts": ["concept name", ...],\n' +
  '  "relationships": [{"from": "concept1", "to": "concept2", "weight": 1.0}, ...],\n' +
  '  "events": [{"name": "event name", "date": null}, ...]\n' +
  '}\n\n' +
  'Rules:\n' +
  '- concepts: key noun phrases, normalized to lowercase\n' +
  '- relationships: pairs of concepts that are meaningfully connected\n' +
  '- events: named occurrences with optional ISO8601 date or null\n' +
  '- Return empty arrays if none found\n\n' +
  'Text:\n' + item.chunk_text;

const requestBody = JSON.stringify({
  model: 'llama3.2',
  messages: [{ role: 'user', content: prompt }],
  stream: false,
  options: { temperature: 0.1 },
});

const callKong = async () => {
  const res = await $helpers.httpRequest({
    method: 'POST',
    url: `${kongUrl}/notebooklm/chat`,
    headers: { 'Content-Type': 'application/json' },
    body: requestBody,
  });
  const parsed = typeof res === 'string' ? JSON.parse(res) : res;
  return (
    parsed?.message?.content ||
    parsed?.choices?.[0]?.message?.content ||
    ''
  );
};

const extractJSON = (text) => {
  const match = text.match(/\{[\s\S]*\}/);
  if (!match) return null;
  try {
    const data = JSON.parse(match[0]);
    if (!Array.isArray(data.concepts)) return null;
    return data;
  } catch {
    return null;
  }
};

let graphData = { concepts: [], relationships: [], events: [] };

try {
  const content1 = await callKong();
  let parsed = extractJSON(content1);

  if (!parsed) {
    console.warn(
      `[GraphExtract] Malformed JSON on attempt 1, chunk ${item.chunk_index} of '${item.title}'. Retrying...`
    );
    const content2 = await callKong();
    parsed = extractJSON(content2);
    if (!parsed) {
      console.warn(
        `[GraphExtract] Malformed JSON on retry, chunk ${item.chunk_index}. Using empty arrays.`
      );
    }
  }

  if (parsed) {
    graphData = {
      concepts: (parsed.concepts || [])
        .map((c) => String(c).toLowerCase().trim())
        .filter(Boolean),
      relationships: (parsed.relationships || []).filter(
        (r) => r && r.from && r.to
      ),
      events: (parsed.events || []).filter((e) => e && e.name),
    };
  }
} catch (err) {
  console.warn(`[GraphExtract] Error, chunk ${item.chunk_index}: ${err.message}`);
}

return [{
  json: {
    ...item,
    graph_concepts: graphData.concepts,
    graph_relationships: graphData.relationships,
    graph_events: graphData.events,
  }
}];

// Write Document, Chunk, Concept, and Event nodes to Neo4j via HTTP transactional API.
// All writes use MERGE to ensure idempotency (Spec #2 AC: second ingest = no duplicates).
// Neo4j HTTP endpoint: POST /db/neo4j/tx/commit with { statements: [{statement, parameters}] }
const item = $input.item.json;

const neo4jUrl = process.env.NEO4J_HTTP_URL;
const neo4jUser = process.env.NEO4J_USER;
const neo4jPassword = process.env.NEO4J_PASSWORD;

if (!neo4jUrl) throw new Error('NEO4J_HTTP_URL env var not set in n8n container');
if (!neo4jUser) throw new Error('NEO4J_USER env var not set in n8n container');
if (!neo4jPassword) throw new Error('NEO4J_PASSWORD env var not set in n8n container');

const authHeader =
  'Basic ' + Buffer.from(`${neo4jUser}:${neo4jPassword}`).toString('base64');

const statements = [];

// 1. MERGE Document node
statements.push({
  statement: [
    'MERGE (d:Document {id: $doc_id})',
    'ON CREATE SET',
    '  d.title = $title,',
    '  d.source_type = $source_type,',
    '  d.source_url = $source_url,',
    '  d.notebook = $notebook,',
    '  d.ingested_at = datetime($ingested_at)',
    'ON MATCH SET d.title = $title',
    'RETURN d.id AS doc_id',
  ].join('\n'),
  parameters: {
    doc_id: item.doc_id,
    title: item.title,
    source_type: item.source_type,
    source_url: item.source_url || '',
    notebook: item.notebook,
    ingested_at: item.ingested_at,
  },
});

// 2. MERGE Chunk node + PART_OF edge to Document
statements.push({
  statement: [
    'MATCH (d:Document {id: $doc_id})',
    'MERGE (ch:Chunk {id: $chunk_id})',
    'ON CREATE SET',
    '  ch.chunk_index = $chunk_index,',
    '  ch.notebook = $notebook,',
    '  ch.ingested_at = datetime($ingested_at)',
    'MERGE (ch)-[:PART_OF]->(d)',
    'RETURN ch.id AS chunk_id',
  ].join('\n'),
  parameters: {
    doc_id: item.doc_id,
    chunk_id: item.chunk_id,
    chunk_index: item.chunk_index,
    notebook: item.notebook,
    ingested_at: item.ingested_at,
  },
});

// 3. MERGE Concept nodes + MENTIONS edges from Chunk
for (const concept of (item.graph_concepts || [])) {
  statements.push({
    statement: [
      'MERGE (c:Concept {name: $name})',
      'ON CREATE SET c.notebooks = [$notebook]',
      'ON MATCH SET c.notebooks =',
      '  CASE WHEN $notebook IN c.notebooks',
      '       THEN c.notebooks',
      '       ELSE c.notebooks + [$notebook] END',
      'WITH c',
      'MATCH (ch:Chunk {id: $chunk_id})',
      'MERGE (ch)-[:MENTIONS]->(c)',
    ].join('\n'),
    parameters: {
      name: concept,
      notebook: item.notebook,
      chunk_id: item.chunk_id,
    },
  });
}

// 4. MERGE RELATED_TO edges between concepts
for (const rel of (item.graph_relationships || [])) {
  const from = String(rel.from).toLowerCase().trim();
  const to = String(rel.to).toLowerCase().trim();
  if (!from || !to || from === to) continue;
  statements.push({
    statement: [
      'MERGE (a:Concept {name: $from})',
      'MERGE (b:Concept {name: $to})',
      'MERGE (a)-[r:RELATED_TO]->(b)',
      'ON CREATE SET r.weight = $weight',
      'ON MATCH SET r.weight = (r.weight + $weight) / 2.0',
    ].join('\n'),
    parameters: { from, to, weight: rel.weight || 1.0 },
  });
}

// 5. MERGE Event nodes + REFERENCES edges from Chunk
for (const event of (item.graph_events || [])) {
  const eventName = String(event.name).trim();
  if (!eventName) continue;
  statements.push({
    statement: [
      'MERGE (e:Event {name: $name, notebook: $notebook})',
      'ON CREATE SET e.date = $date',
      'WITH e',
      'MATCH (ch:Chunk {id: $chunk_id})',
      'MERGE (ch)-[:REFERENCES]->(e)',
    ].join('\n'),
    parameters: {
      name: eventName,
      notebook: item.notebook,
      date: event.date || null,
      chunk_id: item.chunk_id,
    },
  });
}

try {
  const res = await $helpers.httpRequest({
    method: 'POST',
    url: `${neo4jUrl}/db/neo4j/tx/commit`,
    headers: {
      'Content-Type': 'application/json',
      Accept: 'application/json',
      Authorization: authHeader,
    },
    body: JSON.stringify({ statements }),
  });

  const parsed = typeof res === 'string' ? JSON.parse(res) : res;
  if (parsed.errors && parsed.errors.length > 0) {
    throw new Error(`Neo4j errors: ${JSON.stringify(parsed.errors)}`);
  }
} catch (err) {
  // Re-throw — Neo4j write failure must not be swallowed (CONSTITUTION III.3)
  throw new Error(`[WriteNeo4j] chunk ${item.chunk_id}: ${err.message}`);
}

return [{ json: item }];

// 1. Embed chunk text via Kong /notebooklm/embed (nomic-embed-text, 768-dim).
// 2. Upsert to Qdrant with chunk_id as point ID and neo4j_chunk_id in payload.
//
// chunk_id == Qdrant point ID == Neo4j Chunk.id  ← the cross-store link (Spec #2 AC)
const item = $input.item.json;

const kongUrl = process.env.KONG_PROXY_URL;
const qdrantUrl = process.env.QDRANT_URL;

if (!kongUrl) throw new Error('KONG_PROXY_URL env var not set in n8n container');
if (!qdrantUrl) throw new Error('QDRANT_URL env var not set in n8n container');

// ── Step 1: embed ──────────────────────────────────────────────────────────
let vector;
try {
  const embedRes = await $helpers.httpRequest({
    method: 'POST',
    url: `${kongUrl}/notebooklm/embed`,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model: 'nomic-embed-text',
      input: item.chunk_text,
    }),
  });

  const parsed = typeof embedRes === 'string' ? JSON.parse(embedRes) : embedRes;
  // Handle Ollama native format and OpenAI-compatible format
  vector =
    parsed?.embeddings?.[0] ||
    parsed?.data?.[0]?.embedding ||
    parsed?.embedding;

  if (!vector || !Array.isArray(vector) || vector.length !== 768) {
    throw new Error(
      `Expected 768-dim vector, got: ${JSON.stringify(parsed).substring(0, 200)}`
    );
  }
} catch (err) {
  throw new Error(`[Embed] chunk ${item.chunk_id}: ${err.message}`);
}

// ── Step 2: upsert to Qdrant ───────────────────────────────────────────────
try {
  const qdrantRes = await $helpers.httpRequest({
    method: 'PUT',
    url: `${qdrantUrl}/collections/${item.notebook}/points`,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      points: [{
        id: item.chunk_id,
        vector,
        payload: {
          chunk_text: item.chunk_text,
          summary: item.summary || '',
          tags: item.tags || [],
          title: item.title,
          source_type: item.source_type,
          source_url: item.source_url || '',
          chunk_index: item.chunk_index,
          total_chunks: item.total_chunks,
          ingested_at: item.ingested_at,
          neo4j_chunk_id: item.chunk_id,
        },
      }],
    }),
  });

  const parsed = typeof qdrantRes === 'string' ? JSON.parse(qdrantRes) : qdrantRes;
  if (parsed?.status !== 'ok') {
    throw new Error(`Qdrant upsert failed: ${JSON.stringify(parsed)}`);
  }
} catch (err) {
  throw new Error(`[Qdrant] chunk ${item.chunk_id}: ${err.message}`);
}

return [{
  json: {
    chunk_id: item.chunk_id,
    chunk_index: item.chunk_index,
    doc_id: item.doc_id,
    notebook: item.notebook,
    concepts_count: (item.graph_concepts || []).length,
  }
}];
